// Character portraits for MonoMate's coaches and bots. The images are generated by
// scripts/make-portraits.mjs from the Notionists illustration set by Zoish (CC0 1.0).
import React, { useEffect, useState } from 'react';
import { Animated, Image, View } from 'react-native';
import { PORTRAITS } from '../assets/portraits';
import { B, C } from '../lib/theme';

export type Mood = 'neutral' | 'happy' | 'sad' | 'surprised';
export type Who = keyof typeof PORTRAITS;

const MOODS: Mood[] = ['neutral', 'happy', 'sad', 'surprised'];

export const isWho =(id: string | undefined): id is Who => !!id && id in PORTRAITS;

/** A character portrait in a heavy black frame. It bounces whenever `talkKey` or the mood changes. */
export function Portrait({ who, size = 56, mood = 'neutral', talkKey, dim }: { who: Who; size?: number; mood?: Mood; talkKey?: string | number; dim?: boolean }) {
  const [v] = useState(() => new Animated.Value(1));
  const key = `${talkKey ?? ''}|${mood}`;
  const [shown, setShown] = useState(key);
  if (shown !== key) {
    setShown(key);
    v.setValue(0);
  }
  useEffect(() => {
    Animated.spring(v, { toValue: 1, useNativeDriver: true, speed: 18, bounciness: 12 }).start();
  }, [shown, v]);
  return (
    <Animated.View
      style={{
        opacity: dim ? 0.35 : 1,
        transform: [
          { scale: v.interpolate({ inputRange: [0, 1], outputRange: [0.9, 1] }) },
          { rotate: v.interpolate({ inputRange: [0, 0.5, 1], outputRange: ['0deg', '-3deg', '0deg'] }) },
        ],
      }}
    >
      <View style={{ width: size, height: size, borderWidth: B.w, borderColor: C.ink, backgroundColor: C.paper, overflow: 'hidden' }}>
        {/* All four moods stay loaded; only the current one is visible. Swapping the image source
            instead made Android show an empty frame for a moment on every mood change. */}
        {MOODS.map((m) => (
          <Image
            key={m}
            source={PORTRAITS[who][m]}
            style={{ position: 'absolute', width: size - 2 * B.w, height: size - 2 * B.w, opacity: m === mood ? 1 : 0 }}
            resizeMode="cover"
            fadeDuration={0}
          />
        ))}
      </View>
    </Animated.View>
  );
}
